func (o *PaymentMethod) isValidVerificationStatus() bool {
	var allowedEnumValues = []string{"valid", "pending", "invalid", "rejected"}
	for _, allowed := range allowedEnumValues {
		if o.GetVerificationStatus() == allowed {
			return true
		}
	}
	return false
}
